"""Verified local caches and a vectorized, common candidate beam decoder."""
from pathlib import Path
import numpy as np
import torch

from .recovery076_data import CATEGORIES,read,sha,validate_manifest,load_rows


def development_rows(manifest_path,grid=24,cache=None):
    path=Path(manifest_path);manifest=validate_manifest(read(path))
    allowed={r['id']:r for r in manifest['rows'] if r['split'] in ('train','validation')}
    if not cache:return load_rows(path,{'train','validation'},grid)
    # This is a local cache generated by this project, never an uploaded pickle.
    saved=torch.load(cache,map_location='cpu',weights_only=False)
    if saved['key']!={'manifest_sha256':sha(path),'grid':grid}:raise ValueError('Cache key mismatch')
    rows=saved['rows']
    if {r['row']['id'] for r in rows}!=set(allowed) or len(rows)!=len(allowed):
        raise ValueError('Cache must contain exactly train+validation, without test or duplicates')
    verified=set()
    for r in rows:
        meta=allowed[r['row']['id']]
        if r['row']!=meta:raise ValueError('Cache metadata differs from explicit manifest')
        if meta['status']=='ok':
            for f in ('input','target'):
                source=path.parent/meta[f]
                if source not in verified:
                    if sha(source)!=meta[f+'_sha256']:raise ValueError('Frozen source hash mismatch')
                    verified.add(source)
        if meta['split'] not in ('train','validation'):raise ValueError('Test in training cache')
    return rows


def decode_fast(outputs,batch,candidates=40,beam=32):
    """The 076 candidate/NMS/object ordering and penalties, vectorized.

    Used unchanged for the trained scorer and the fixed physical kernel.
    No greedy threshold based on ground truth or model confidence is involved.
    """
    if candidates<1 or beam<1:raise ValueError('Positive search budgets required')
    logp=outputs['log_prob'].detach().cpu().numpy();centres=batch['centres'].cpu().numpy()
    sizes=batch['sizes'].cpu().numpy();valid=batch['valid'].cpu().numpy()
    cats=batch['category'].cpu().numpy();eligible=batch['candidate_valid'].cpu().numpy();results=[]
    for b in range(len(logp)):
        slots=sorted(np.flatnonzero(valid[b]),key=lambda j:-float(logp[b,j].max()))
        costs=np.zeros(1);chosen=np.empty((1,0,4));chosen_slots=[]
        for slot in slots:
            pool=[];ids=[]
            for i in np.argsort(-logp[b,slot],kind='stable'):
                if not eligible[b,slot,i]:continue
                pos=centres[b,slot,i];size=sizes[b,slot,i]
                if pool:
                    p=np.asarray(pool)
                    same=np.all(np.isclose(size,p[:,2:]-p[:,:2]),axis=-1)
                    near=np.linalg.norm(pos-(p[:,:2]+p[:,2:])/2,axis=-1)<.18
                    if np.any(same&near):continue
                pool.append(np.r_[pos-size/2,pos+size/2]);ids.append(i)
                if len(pool)>=candidates:break
            if not pool:raise ValueError('No candidate; do not silently omit room')
            boxes=np.asarray(pool);scores=-logp[b,slot,ids]
            joint=costs[:,None]+scores[None]
            if chosen.shape[1]:
                lo=np.maximum(chosen[:,:,None,:2],boxes[None,None,:,:2])
                hi=np.minimum(chosen[:,:,None,2:],boxes[None,None,:,2:])
                inter=np.maximum(0,hi-lo).prod(-1)
                area=np.prod(chosen[:,:,2:]-chosen[:,:,:2],-1)[:,:,None]
                area2=np.prod(boxes[:,2:]-boxes[:,:2],-1)[None,None]
                overlap=inter/np.maximum(1e-10,area+area2-inter)
                joint=joint+20*overlap.sum(1)
            keep=np.argsort(joint.ravel(),kind='stable')[:beam]
            parent,proposal=np.unravel_index(keep,joint.shape)
            chosen=np.concatenate([chosen[parent],boxes[proposal,None]],1)
            costs=joint[parent,proposal];chosen_slots.append(slot)
        counts={};out={}
        for j,slot in sorted(enumerate(chosen_slots),key=lambda x:x[1]):
            category=CATEGORIES[cats[b,slot]];n=counts.get(category,0);counts[category]=n+1
            out[f'{category}#{n}']=chosen[0,j].tolist()
        results.append(out)
    return results
